<script>
(function () {
const state = window.consultationState;
const hiddenMap = {chiefComplaints:'#chiefComplaintsField',aggravatingFactors:'#aggravatingFactorsField',relievingFactors:'#relievingFactorsField',associatedSymptoms:'#associatedSymptomsField',pastMedicalHistory:'#pastMedicalHistoryField',surgicalHistory:'#surgicalHistoryField',familyHistory:'#familyHistoryField',drugAllergies:'#drugAllergiesField',chronicConditions:'#chronicConditionsField',ongoingMedications:'#ongoingMedicationsField',diagnoses:'#diagnosesField',examinations:'#examinationsField',investigations:'#investigationsField',prescriptions:'#prescriptionsField'};
function syncHidden(){Object.keys(hiddenMap).forEach(key=>$(hiddenMap[key]).val(JSON.stringify(state[key]||[])));}
function renderTags(){ $('[data-tag-group]').each(function(){ const key=$(this).data('tag-group'); const box=$(this).empty(); (state[key]||[]).forEach((item,index)=>{ const pill=$('<span class="tag-pill"></span>').text(item+' '); pill.append($('<button type="button"><i class="bi bi-x-lg"></i></button>').on('click',()=>{ state[key].splice(index,1); renderTags(); syncHidden(); })); box.append(pill);}); const input=$('<input class="tag-input" placeholder="Type and press Enter">'); input.on('keydown',function(e){ if(e.key!=='Enter') return; e.preventDefault(); const value=$(this).val().trim(); if(!value) return; state[key].push(value); renderTags(); syncHidden(); }); box.append(input); }); }
function updateVitalsSummary(){ const bp=[$('[name="bp_systolic"]').val(),$('[name="bp_diastolic"]').val()].filter(Boolean).join(' / '); $('#summaryBp').text(bp||'-'); $('#summaryHr').text($('[name="heart_rate"]').val()||'-'); $('#summarySpo2').text($('[name="spo2"]').val()||'-'); $('#summaryTemp').text($('[name="temperature"]').val()||'-'); const weight=parseFloat($('[name="weight"]').val()); const height=parseFloat($('[name="height"]').val()); if(!Number.isNaN(weight)&&!Number.isNaN(height)&&height>0){ $('[name="bmi"]').val((weight/Math.pow(height/100,2)).toFixed(1)); } $('#summaryBmi').text($('[name="bmi"]').val()||'-'); }
function attachLookup(input,url,render,pick){ const wrap=input.closest('.lookup'); const list=$('<div class="lookup-list"></div>'); wrap.append(list); let timer=null; input.on('input',function(){ const q=this.value.trim(); clearTimeout(timer); if(q.length<2){ list.removeClass('open').empty(); return; } timer=setTimeout(()=>{$.get(url,{q},items=>{ list.empty(); if(!items.length){ list.append('<div class="lookup-item">No matches found.</div>').addClass('open'); return; } items.forEach(item=>{ const ui=render(item); const row=$('<div class="lookup-item"></div>').append(`<div>${ui.title}</div>`).append(ui.sub?`<div class="lookup-sub">${ui.sub}</div>`:''); row.on('click',()=>{ pick(item); list.removeClass('open').empty(); }); list.append(row);}); list.addClass('open');});},250);}); $(document).on('click',e=>{ if(!wrap.is(e.target)&&wrap.has(e.target).length===0) list.removeClass('open').empty();}); }
function renderExaminations(){ const list=$('#examinationsList').empty(); if(!state.examinations.length) state.examinations.push({system_name:'General System',finding_status:'normal',notes:''}); state.examinations.forEach((row,index)=>{ const box=$(`<div class="row-box"><div class="grid-3"><div><label class="field-label">System</label><input class="field system-name"></div><div><label class="field-label">Status</label><select class="select system-status"><option value="normal">Normal</option><option value="abnormal">Abnormal</option></select></div><div style="display:flex;align-items:end;justify-content:flex-end"><button type="button" class="btn-soft remove-row"><i class="bi bi-trash"></i> Remove</button></div></div><div style="margin-top:12px"><label class="field-label">Notes</label><textarea class="textarea system-notes"></textarea></div></div>`); box.find('.system-name').val(row.system_name||'').on('input',function(){ state.examinations[index].system_name=this.value; syncHidden();}); box.find('.system-status').val(row.finding_status||'normal').on('change',function(){ state.examinations[index].finding_status=this.value; syncHidden();}); box.find('.system-notes').val(row.notes||'').on('input',function(){ state.examinations[index].notes=this.value; syncHidden();}); box.find('.remove-row').on('click',function(){ state.examinations.splice(index,1); renderExaminations(); syncHidden();}); list.append(box); }); }
function renderDiagnoses(){ const list=$('#diagnosisList').empty(); if(!state.diagnoses.length) state.diagnoses.push({diagnosis_name:'',icd10_code_id:'',icd10_code:'',diagnosis_type:'provisional',clinical_status:'active'}); state.diagnoses.forEach((row,index)=>{ const box=$(`<div class="row-box"><div class="grid-3"><div class="lookup"><label class="field-label">Diagnosis</label><input class="field diag-name"></div><div><label class="field-label">ICD-10</label><input class="field diag-code" readonly></div><div style="display:flex;align-items:end;justify-content:flex-end"><button type="button" class="btn-soft remove-row"><i class="bi bi-trash"></i> Remove</button></div></div><div class="grid-2" style="margin-top:12px"><div><label class="field-label">Type</label><select class="select diag-type"><option value="provisional">Provisional</option><option value="final">Final</option><option value="differential">Differential</option></select></div><div><label class="field-label">Status</label><select class="select diag-status"><option value="active">Active</option><option value="resolved">Resolved</option><option value="chronic">Chronic</option></select></div></div></div>`); const name=box.find('.diag-name'); name.val(row.diagnosis_name||'').on('input',function(){ state.diagnoses[index].diagnosis_name=this.value; syncHidden();}); box.find('.diag-code').val(row.icd10_code||''); box.find('.diag-type').val(row.diagnosis_type||'provisional').on('change',function(){ state.diagnoses[index].diagnosis_type=this.value; syncHidden();}); box.find('.diag-status').val(row.clinical_status||'active').on('change',function(){ state.diagnoses[index].clinical_status=this.value; syncHidden();}); box.find('.remove-row').on('click',function(){ state.diagnoses.splice(index,1); renderDiagnoses(); syncHidden();}); attachLookup(name,"{{ route('consultations.search.icd10') }}",item=>({title:item.name,sub:item.code}),item=>{ state.diagnoses[index].diagnosis_name=item.name; state.diagnoses[index].icd10_code_id=item.id; state.diagnoses[index].icd10_code=item.code; name.val(item.name); box.find('.diag-code').val(item.code); syncHidden();}); list.append(box); }); }
function renderInvestigations(){ const box=$('#investigationTagBox').empty(); (state.investigations||[]).forEach((item,index)=>{ const text=typeof item==='object'?item.test_name:item; const pill=$('<span class="tag-pill"></span>').text(text+' '); pill.append($('<button type="button"><i class="bi bi-x-lg"></i></button>').on('click',()=>{ state.investigations.splice(index,1); renderInvestigations(); syncHidden();})); box.append(pill);}); const input=$('<input class="tag-input" placeholder="Type test and press Enter">'); input.on('keydown',function(e){ if(e.key!=='Enter') return; e.preventDefault(); const value=$(this).val().trim(); if(!value) return; state.investigations.push({test_name:value}); renderInvestigations(); syncHidden();}); box.append(input); }
function renderPrescriptions(){ const list=$('#prescriptionList').empty(); if(!state.prescriptions.length) state.prescriptions.push({medicine_id:'',medicine_name:'',pack:'',frequency:'OD',duration:'',instruction:'After Food',details:''}); state.prescriptions.forEach((row,index)=>{ const box=$(`<div class="row-box"><div class="grid-3"><div class="lookup"><label class="field-label">Medicine</label><input class="field med-name"></div><div><label class="field-label">Pack</label><input class="field med-pack"></div><div style="display:flex;align-items:end;justify-content:flex-end"><button type="button" class="btn-soft remove-row"><i class="bi bi-trash"></i> Remove</button></div></div><div class="grid-3" style="margin-top:12px"><div><label class="field-label">Frequency</label><select class="select med-frequency"><option value="OD">OD</option><option value="BD">BD</option><option value="TDS">TDS</option><option value="HS">HS</option><option value="SOS">SOS</option></select></div><div><label class="field-label">Duration</label><input class="field med-duration"></div><div><label class="field-label">Instruction</label><select class="select med-instruction"><option value="Before Food">Before Food</option><option value="After Food">After Food</option><option value="With Food">With Food</option><option value="At Night">At Night</option></select></div></div><div style="margin-top:12px"><label class="field-label">Details</label><textarea class="textarea med-details"></textarea></div></div>`); const name=box.find('.med-name'); name.val(row.medicine_name||'').on('input',function(){ state.prescriptions[index].medicine_name=this.value; syncHidden();}); box.find('.med-pack').val(row.pack||'').on('input',function(){ state.prescriptions[index].pack=this.value; syncHidden();}); box.find('.med-frequency').val(row.frequency||'OD').on('change',function(){ state.prescriptions[index].frequency=this.value; syncHidden();}); box.find('.med-duration').val(row.duration||'').on('input',function(){ state.prescriptions[index].duration=this.value; syncHidden();}); box.find('.med-instruction').val(row.instruction||'After Food').on('change',function(){ state.prescriptions[index].instruction=this.value; syncHidden();}); box.find('.med-details').val(row.details||'').on('input',function(){ state.prescriptions[index].details=this.value; syncHidden();}); box.find('.remove-row').on('click',function(){ state.prescriptions.splice(index,1); renderPrescriptions(); syncHidden();}); attachLookup(name,"{{ route('consultations.search.medicines') }}",item=>({title:item.name,sub:[item.pack,item.manufacturer].filter(Boolean).join(' · ')}),item=>{ state.prescriptions[index].medicine_id=item.id; state.prescriptions[index].medicine_name=item.name; state.prescriptions[index].pack=item.pack||''; state.prescriptions[index].details=item.details||''; name.val(item.name); box.find('.med-pack').val(item.pack||''); box.find('.med-details').val(item.details||''); syncHidden();}); list.append(box); }); }
function submitConsultation(status,print){ syncHidden(); $('#statusField').val(status); $('#printAfterSave').val(print?'1':'0'); $('#consultationForm').trigger('submit'); }
$('#openHistoryBtn').on('click',()=>$('#historyModal').addClass('open')); $('#closeHistoryBtn,#saveHistoryBtn').on('click',()=>{ syncHidden(); $('#historyModal').removeClass('open');}); $('.follow-chip').on('click',function(){ $('.follow-chip').removeClass('active'); $(this).addClass('active'); $('#followUpLabelField').val($(this).data('followup'));}); $('.vital-input').on('input',updateVitalsSummary); $('#addExaminationBtn').on('click',()=>{ state.examinations.push({system_name:'',finding_status:'normal',notes:''}); renderExaminations(); syncHidden();}); $('#addDiagnosisBtn').on('click',()=>{ state.diagnoses.push({diagnosis_name:'',icd10_code_id:'',icd10_code:'',diagnosis_type:'provisional',clinical_status:'active'}); renderDiagnoses(); syncHidden();}); $('#addInvestigationBtn').on('click',()=>{ const value=prompt('Enter investigation / test name'); if(value&&value.trim()){ state.investigations.push({test_name:value.trim()}); renderInvestigations(); syncHidden(); }}); $('#addPrescriptionBtn').on('click',()=>{ state.prescriptions.push({medicine_id:'',medicine_name:'',pack:'',frequency:'OD',duration:'',instruction:'After Food',details:''}); renderPrescriptions(); syncHidden();}); $('#saveDraftBtn').on('click',()=>submitConsultation('draft',false)); $('#finalizeBtn').on('click',()=>submitConsultation('finalized',false)); $('#finalizePrintBtn').on('click',()=>submitConsultation('finalized',true)); renderTags(); renderExaminations(); renderDiagnoses(); renderInvestigations(); renderPrescriptions(); updateVitalsSummary(); syncHidden();
})();
</script>
